    "examplePrompt": "這是我同業的 YouTube 頻道播放清單：（貼上網址）。先幫我把裡面所有影片列出來，包含標題、片長和觀看數，照觀看數由高到低排。列完之後告訴我前十支影片的主題大概分成幾類，哪一類最多人看。接著挑觀看數最高的三支，把影片內容轉成文字，整理出他們怎麼開場、講了哪些賣點、最後怎麼收尾。最後幫我想三則 Threads 貼文的方向，不要抄他們的內容，是我們可以用自己角度講的題目。",
