    "examplePrompt": "我們決定十月要在 momo 上架八支新的香氛蠟燭，主打秋冬跟送禮。企劃已經定了：定價 590、走禮盒組、搭一檔滿千折百。請幫我寫一張執行單，執行的人是剛來一個月的助理，對 momo 後台不太熟。每一步要小到兩三分鐘做得完，寫清楚會碰到哪些東西、要先準備什麼素材、做完長什麼樣才算過關。不要出現「細節後補」這種寫法。寫完幫我對照企劃檢查一次，看有沒有漏掉的。",
