    "examplePrompt": "我們是化妝品品牌，文案規則是這樣：品牌名一律寫成 AUS LIFE，中間空一格；不能出現美白、抗老、修復、療效這類字眼；不要用您，一律用你；蝦皮商品頁不能夾網頁語法，只能用純文字符號；價格一律寫成 NT$ 加數字。這是我們新的商品頁草稿（貼上文案）。請你逐段檢查，把不符合規則的句子標出來，說明違反哪一條，並給一個改好的版本。沒問題的段落不用列出來，我只要看要改的地方。",
