    "examplePrompt": "這是蝦皮聊聊的客訴，請幫我做一份回覆劇本。客人七月二十二號下單一組保養組合，七月二十五號出貨，到今天物流還顯示在轉運中。他剛剛傳：到底要不要出貨？？？前天問一次沒人理，這種賣家也敢做生意，我要去評價。我這邊的事實：貨確實出了，是宅配塞車；我可以今天再補寄一組先出，或全額退款兩個工作天。請告訴我這次絕對不能說的話，再給我一則可以直接送出的回覆，還有他如果繼續鬧我要怎麼接。",
