    "examplePrompt": "幫我把下面這篇文章做成一組 IG 輪播圖卡，直式比例，六到八張。第一張是封面，要一句話讓人想滑下去；後面每張只講一個重點，字不要多。風格走雜誌編輯感，配色偏暖，品牌主色是 #D4B8A8。我附了三張商品實拍照，請放在講質地跟使用方式的那幾張，人臉不要被文字壓到。做之前先給我「第幾張／講什麼／用哪張照片」的清單讓我確認，我點頭你再排版出圖。文章內容如下：（貼上文章）",
